                <h3>1. Ce este Preistoria?</h3>
                <p><strong>Preistoria</strong> este prima și cea mai lungă epocă din istoria omenirii. Ea ține de la apariția omului și până la inventarea scrisului.</p>
                <p>Conform lui Charles Darwin, oamenii au apărut prin evoluție în Africa de Est. Primii strămoși (cum a fost australopitecul) au învățat să meargă în două picioare și să folosească mâinile pentru a găsi hrană și a se apăra.</p>

