                <p>În secolul al III-lea, Imperiul Roman a intrat într-o perioadă lungă de decădere. Din cauza războaielor civile dintre generali și a atacurilor barbarilor, romanii au fost nevoiți să abandoneze provinciile greu de apărat, precum <strong>Dacia</strong>, retrăgându-se la Dunăre.</p>

