        summary: `
            <h3>1. Un țar uriaș și plin de energie</h3>
            <p>Petru I (numit și <strong>Petru cel Mare</strong>) a fost un conducător neobișnuit al Rusiei: avea o înălțime de peste doi metri, o forță fizică uriașă și o dorință imensă de a învăța lucruri noi. În anii <strong>1697-1698</strong>, a întreprins o celebră călătorie de studiu prin vestul Europei (Occident), numită <em>„Marea Ambasadă”</em>, unde a lucrat incognito în șantiere navale pentru a învăța construirea corăbiilor. Întors acasă, s-a hotărât să transforme Rusia dintr-o țară înapoiată într-o mare putere modernă.</p>

            <h3>2. Regulile noi: Fără bărbi lungi și calendar european</h3>
            <p>Pentru a-i face pe ruși să trăiască la fel ca oamenii din vestul Europei, Petru a luat măsuri foarte ferme:</p>
            <ul>
                <li><strong>Taxa pe barbă:</strong> Bărbații erau obligați să își radă bărbele lungi tradiționale. Cei care refuzau trebuiau să plătească un impozit special și să poarte o medalie din bronz care dovedea că au achitat taxa.</li>
                <li><strong>Moda europeană:</strong> A interzis purtarea hainelor boierești lungi (caftane), impunând haine scurte de tip occidental.</li>
                <li><strong>Reforma calendarului (1699):</strong> A schimbat vechiul calendar, mutând sărbătorirea Anului Nou de la 1 septembrie la <strong>1 ianuarie</strong>.</li>
            </ul>

            <h3>3. Războaie, bătălii decisive și o nouă capitală</h3>
            <p>Petru știa că o țară puternică are nevoie de ieșire la mare și de corăbii. Pentru a dezvolta fabricile și atelierele (manufacturi), le-a oferit meșterilor <strong>împrumuturi fără dobândă</strong> și i-a <strong>scutit de impozite</strong>.</p>
            <p>A purtat războaie împotriva <strong>Imperiului Otoman</strong> (unde a obținut cetatea Azov în 1696) și împotriva <strong>Suediei</strong> în <em>Marele Război al Nordului (1700-1721)</em>. În celebra <strong>Bătălie de la Poltava (1709)</strong>, armata lui Petru a zdrobit armata regelui suedez Carol al XII-lea, asigurând Rusiei controlul la Marea Baltică.</p>
            <p>În anul <strong>1703</strong>, la vărsarea râului Neva în Marea Baltică, Petru a început construcția unui oraș superb: <strong>Sankt Petersburg</strong>. În anul <strong>1712</strong>, el a mutat oficial capitala de la Moscova acolo, numind noul oraș „fereastra Rusiei spre Europa”.</p>
        `,
