        title: "4. Viața în tranșee și „frontul de acasă”",
        summary: `
            <h3>1. Ce erau tranșeele și de ce s-a ajuns la războiul de uzură?</h3>
            <p>Pentru a se proteja de noile arme puternice (mitraliere, tunuri), armatele au săpat rețele uriașe de <strong>tranșee</strong>. Acestea erau șanțuri adânci de peste 2 metri și late de 1-3 metri, întărite cu saci de nisip sau bârne și protejate de garduri lungi din sârmă ghimpată.</p>
            <p>Fiind foarte greu de cucerit, tranșeele au transformat lupta într-un <strong>război de poziții (sau de uzură)</strong>. Nimeni nu reușea să înainteze, iar pierderile de vieți omenești au fost uriașe de ambele părți.</p>

            <h3>2. Viața cotidiană a soldaților pe front</h3>
            <p>Condițiile de trai ale militarilor din tranșee erau cumplite:</p>
            <ul>
                <li>Mâncarea era puțină, iar igiena corporală lipsea cu desăvârșire.</li>
                <li>Dormeau direct pe pământul ud sau pe saltele improvizate.</li>
                <li>Ploaia și ninsoarea inundau șanțurile, transformându-le în noroi. Din cauza frigului și a umezelii, mulți soldați se îmbolnăveau grav, iar spitalele de campanie abia făceau față.</li>
            </ul>

            <h3>3. „Frontul de acasă” și suferințele civililor</h3>
            <p>În spatele liniei de luptă exista <strong>„frontul de acasă”</strong>, al cărui scop era aprovizionarea armatei cu hrană, haine și muniție.</p>
            <p>Lipsa bărbaților s-a simțit puternic: în Germania anului 1918, peste <strong>55% din muncitorii din fabrici erau femei</strong>. Muncile agricole au devenit extrem de grele, mai ales că animalele de tracțiune (caii și boii) fuseseră luate pentru nevoile armatei.</p>
            <p>Lipsurile au dus la <strong>foamete și epidemii cumplite</strong>. Din cauza acestora, aproape 7 milioane de civili au murit în timpul războiului – un număr aproape egal cu cel al soldaților căzuți pe câmpul de luptă.</p>
        `,
