        title: "5. România și Primul Război Mondial",
        summary: `
            <h3>1. Neutralitatea (1914–1916)</h3>
            <p>Deși România era din 1883 într-o alianță secretă cu Puterile Centrale, la izbucnirea războiului în 1914, Regele Carol I și Consiliul de Coroană au decis ca țara să rămână <strong>neutră</strong>.</p>
            <p>Opinia publică din România nu dorea o alianță cu Austro-Ungaria, deoarece românii din Transilvania, Banat și Bucovina erau lipsiți de drepturi politice și supuși deznaționalizării.</p>

            <h3>2. Intrarea în război alături de Antanta</h3>
            <p>Românii își doreau unirea cu teritoriile românești din Austro-Ungaria. Moartea Regelui Carol I în 1914 și urcarea pe tron a <strong>Regelui Ferdinand I și a Reginei Maria</strong> (care susțineau Antanta) au fost decisive.</p>
            <p>La <strong>4 august 1916</strong>, România a semnat tratatul cu Antanta și a declarat război Austro-Ungariei. Armata română a trecut Carpații în Transilvania cu mult entuziasm.</p>

            <h3>3. Campania din 1916 și retragerea în Moldova</h3>
            <p>Puterile Centrale au atacat masiv din două direcții: dinspre nord-vest (germanii și austro-ungarii) și dinspre sud (bulgarii și germanii). Fiind atacată pe două fronturi, armata română a fost nevoită să se retragă.</p>

            <p>Sudul țării și Bucureștiul au fost ocupate. Regele, Guvernul, Parlamentul și Armata s-au retras în <strong>Moldova</strong>, stabilind capitala la Iași. Tot atunci, <strong>Tezaurul României (100 de tone de aur)</strong> a fost trimis la Moscova pentru a fi protejat.</p>

            <h3>4. Reorganizarea și marile victorii din 1917</h3>
            <p>Cu sprijinul Misiunii Militare Franceze conduse de <strong>generalul Henri Berthelot</strong>, armata română a fost dotată cu echipament modern și reorganizată. În vara anului 1917, românii au obținut victorii legendare la <strong>Mărăști, Mărășești și Oituz</strong>, oprind definitiv înaintarea trupelor germane.</p>

            <h3>5. Anul 1918 și Marea Unire</h3>
            <p>După ce Rusia a ieșit din război în urma revoluției, România a rămas izolată și a fost obligată să semneze o pace nefavorabilă. Totuși, victoriile Antantei de pe Frontul de Vest și destrămarea marilor imperii vecine au permis realizarea visului național.</p>
            <p>În anul <strong>1918</strong>, românii au hotărât unirea cu Țara a tuturor provinciilor istorice: <strong>Basarabia, Bucovina, Transilvania și Banatul</strong>, formând <strong>România Mare</strong>.</p>
        `,
