        title: "11. Cetățean și stat în democrație și totalitarism",
        summary: `
            <h3>1. Democrație vs. Totalitarism</h3>
            <p>Perioada interbelică a fost marcată de confruntarea dintre două forme de organizare a statului:</p>
            <ul>
                <li><strong>Democrația:</strong> se bazează pe existența mai multor partide (pluripartidism), alegeri libere, separația puterilor în stat și respectarea drepturilor omului. Poporul controlează conducătorii prin vot.</li>
                <li><strong>Totalitarismul:</strong> puterea este deținută de un singur partid (unipartidism) și un conducător absolut (dictator). Cetățenii își pierd drepturile, iar opoziția este eliminată prin cenzură, teroare și lagăre de concentrare.</li>
            </ul>

            <h3>2. State democratice interbelice</h3>
            <p>Principalele democrații au fost:</p>
            <ul>
                <li><strong>SUA și Marea Britanie:</strong> aveau sisteme bipartite (două partide principale care alternau la guvernare).</li>
                <li><strong>Franța:</strong> republică democratică unde guvernarea se făcea prin coaliții de stânga sau de dreapta.</li>
                <li>Alte state democratice: Elveția, Suedia, Norvegia, Danemarca, Cehoslovacia, Iugoslavia și <strong>România</strong>.</li>
            </ul>

            <h3>3. Regimurile totalitare și spectatorul politic</h3>
            <p>Pe fondul problemelor economice și al nemulțumirilor de după război, au apărut trei mari regimuri totalitare:</p>
            <ul>
                <li><strong>URSS (Uniunea Sovietică):</strong> primul stat totalitar comunist (extremă-stânga), apărut în 1917.</li>
                <li><strong>Italia fascistă:</strong> condusă de Benito Mussolini (extremă-dreapta), instalat la putere după <em>Marșul asupra Romei</em> (1922).</li>
                <li><strong>Germania nazistă:</strong> condusă de Adolf Hitler (extremă-dreapta), din 1933.</li>
            </ul>
        `,
