    summary: `
        <h3> Marile mutări de populație și refugiații</h3>
        <p>După război, Europa nu s-a confruntat doar cu orașe distruse, ci și cu milioane de oameni aflați pe drumuri: văduve, orfani, răniți și refugiați. Modificarea granițelor a dus la str strămutări uriașe de populație. De exemplu, germanii din Polonia și Cehoslovacia au plecat spre Germania, iar românii din Bulgaria s-au întors în România. Toți acești oameni aveau nevoie urgentă de adăpost și de un loc de muncă.</p>

        <h3> De la tancuri la televizoare și lupta cu sărăcia</h3>
        <p>Economia a trebuit transformată rapid din economie de război în economie de pace. Fabricile care înainte construiau tancuri și muniție s-au reorientat spre mașini, televizoare și bunuri de uz casnic. Totuși, primii ani au fost marcați de <b>austeritate</b>: hrana (carnea, zahărul, pâinea) și combustibilul erau încă raționalizate pe bază de cartele. În plus, întoarcerea soldaților a creat șomaj, mulți muncitori organizându-se în <b>sindicate</b> pentru a-și apăra drepturile.</p>

        <h3> „Baby Boom” și drumul spre o viață confortabilă</h3>
        <p>Odată cu venirea păcii, populația Europei a crescut spectaculos, fenomen numit <b>Baby Boom</b> („explozia de bebeluși”), ceea ce a determinat guvernele să investească masiv în școli și spitale. Cu timpul, economiile și-au revenit, aducând prosperitatea: oamenii aveau un loc de muncă stabil, o casă, o mașină și bunuri care le făceau viața mai ușoară (frigider, mașină de spălat, aspirator), dar și acces la produse delicioase precum cafeaua, ciocolata și fructele tropicale.</p>
    `,
