    title: "5. Cultura Cucuteni",
    summary: `
        <h3> Ceramica pictată și motivele decorative</h3>
        <p>Cultura Cucuteni este una dintre cele mai strălucite civilizații eneolitice din Europa, renumită pentru ceramica sa pictată de o mare eleganță. Piese caracteristice sunt atât vasele de uz casnic (străchini, castroane, fructiere, vase de provizii), cât și cele ritualice, precum <b>vasele-binoclu</b> sau cele de tip <b>horă</b>. Ornamentația este realizată în trei culori (<b>tricromie: alb, roșu și negru</b>), folosind motive în spirală sau meandre care acoperă întreaga suprafață.</p>

        <h3> Statuetele antropomorfe și cultul fecundității</h3>
        <p>Așezările Cucuteni au furnizat o multitudine de statuete din lut dedicate cultului fecundității și fertilității. Reprezentările umane au siluete stilizate (lipsite de brațe, cu capul și picioarele modelate sumar), punând accent pe bust și coapse. Statuetele sunt decorate prin incizii sau pictură.</p>

        <h3> Simbolistica spiralei</h3>
        <p>Spirala este elementul decorativ central în arta Cucuteni. Înlănțuită, secționată sau organizată în combinații de șiruri, spirala simbolizează <b>succesiunea ciclurilor naturii</b>, evoluția vieții și ideea de fertilitate, specifică societăților agricole care asociau rodnicia pământului cu fecunditatea feminină.</p>
    `,
